tools.description:
Distill the design tokens out of a project's EXISTING CSS so new components match the app the user already built.

Use this when the user says "match our existing style", "use our design system", "style this like the rest of the app", or you are adding UI to a codebase that already has its own look. This is the inverse of find-design-system / create-design-system: instead of giving the user one of our systems, it reads theirs.

How to use it: read the project's `globals.css` (or wherever the design tokens / CSS custom properties live, e.g. a Tailwind v4 `@theme` block) and pass its full contents as `css`. For a one-file HTML page, pass the whole file as `css`: its `<style>` blocks are its design. The MCP server cannot read your filesystem, so you must paste the text.

Returns: the semantic palette (primary, background, foreground, accent, border, ring, etc.), radius, fonts, shadow scale, and spacing and type scale, plus a pasteable token sheet with every color normalized to `oklch()`. Handles hex, rgb()/rgba(), hsl()/hsla(), named colors, bare Shopify "r,g,b" triplets, and existing oklch values, across `:root`, `.dark`, and `@theme` blocks.

Beyond pasted CSS, `sources` accepts any mix of inputs and merges them (later sources win):
- kind "css": any stylesheet text, same as the `css` param.
- kind "computed": a JSON sample of rendered styles read off the LIVE site, which beats variable-name guessing because it records what elements actually look like. Gather it by running this in the site's browser console and passing the printed JSON:
```js
JSON.stringify((() => {
  const pick = (el, props) => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    return Object.fromEntries(props.map((p) => [p, cs[p]]));
  };
  const clear = (c) => {
    const flat = (c || "").split(" ").join("");
    if (!flat || flat === "transparent") return true;
    // A fill under 10% opacity reads as no fill: Linear's ghost buttons sit at 2%. [BD-1468]
    const alpha = flat.match(/[,/]([0-9.]+%?)\)$/);
    if (!alpha || !/^(rgba|hsla)|\//.test(flat)) return false;
    const a = alpha[1].endsWith("%") ? parseFloat(alpha[1]) / 100 : parseFloat(alpha[1]);
    return a < 0.1;
  };
  // Any CSS colour as [r, g, b]. Chrome reports a colour authored in lab() or
  // oklch() in that form, so a 1px canvas converts what the regex cannot. [BD-1753]
  let canvas = null;
  const rgbOf = (c) => {
    const nums = String(c || "").startsWith("rgb") ? (c.match(/[0-9.]+/g) || []).slice(0, 3).map(Number) : [];
    if (nums.length === 3) return nums;
    try {
      canvas = canvas || document.createElement("canvas").getContext("2d");
      canvas.clearRect(0, 0, 1, 1);
      canvas.fillStyle = "#000";
      canvas.fillStyle = c;
      canvas.fillRect(0, 0, 1, 1);
      return Array.from(canvas.getImageData(0, 0, 1, 1).data.slice(0, 3));
    } catch {
      // No canvas, as in a test page: the colour counts as unreadable, not as an error.
      return null;
    }
  };
  // True when a colour has no alpha, or an alpha of at least 0.9.
  const opaque = (c) => {
    const alpha = (String(c).match(/[0-9.]+%?/g) || [])[3];
    if (alpha === undefined) return true;
    return (alpha.endsWith("%") ? parseFloat(alpha) / 100 : parseFloat(alpha)) >= 0.9;
  };
  const spread = (c) => {
    const rgb = rgbOf(c);
    return rgb ? Math.max(...rgb) - Math.min(...rgb) : 0;
  };
  const luminance = (rgb) => {
    const [r, g, b] = rgb.map((v) => (v / 255 <= 0.03928 ? v / 255 / 12.92 : Math.pow((v / 255 + 0.055) / 1.055, 2.4)));
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const contrast = (a, b) => {
    const x = rgbOf(a);
    const y = rgbOf(b);
    if (!x || !y) return 1;
    const [hi, lo] = [luminance(x), luminance(y)].sort((p, q) => q - p);
    return (hi + 0.05) / (lo + 0.05);
  };
  const seen = (el) => {
    const box = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    return box.width > 0 && box.height > 0 && !(box.bottom <= 0) && !(box.right <= 0) && cs.opacity !== "0" && cs.visibility !== "hidden";
  };
  const ground = () => {
    const body = document.body ? getComputedStyle(document.body).backgroundColor : "";
    if (!clear(body)) return body;
    const html = document.documentElement ? getComputedStyle(document.documentElement).backgroundColor : "";
    return clear(html) ? "rgb(255, 255, 255)" : html;
  };
  // One pass over the visible page: how often each text colour and each
  // padding or gap length appears. [BD-1753]
  let walked = null;
  const walk = () => {
    if (walked) return walked;
    walked = { text: {}, texts: 0, space: {}, font: {} };
    for (const el of Array.from(document.querySelectorAll("body *")).slice(0, 4000)) {
      if (!seen(el)) continue;
      const cs = getComputedStyle(el);
      for (const prop of ["paddingTop", "paddingRight", "paddingBottom", "paddingLeft", "rowGap", "columnGap"]) {
        const raw = String(cs[prop] || "");
        const px = parseFloat(raw);
        if (raw.endsWith("px") && px > 0) {
          const key = Math.round(px * 2) / 2 + "px";
          walked.space[key] = (walked.space[key] || 0) + 1;
        }
      }
      if (Array.from(el.childNodes || []).some((n) => n.nodeType === 3 && String(n.textContent).trim())) {
        walked.texts++;
        walked.text[cs.color] = (walked.text[cs.color] || 0) + 1;
        walked.font[cs.fontFamily] = (walked.font[cs.fontFamily] || 0) + 1;
      }
    }
    return walked;
  };
  const page = (props) => {
    const sample = pick(document.body, props);
    if (!sample) return sample;
    sample.backgroundColor = ground();
    // A body colour that almost no text renders in is an inherited default,
    // not the text colour: Stripe's body says black and its copy sets navy.
    // Take the frequent neutral text colour that stands out most. [BD-1753]
    const { text, texts, font } = walk();
    // The same holds for the font: Duolingo's body says sans-serif and its
    // copy sets duolingo-sans, so take the face most text renders in. [BD-1755]
    if (sample.fontFamily && texts >= 20 && (font[sample.fontFamily] || 0) < texts * 0.01) {
      const main = Object.entries(font).sort((a, b) => b[1] - a[1])[0];
      if (main && main[1] >= texts * 0.3) sample.fontFamily = main[0];
    }
    if (sample.color && texts >= 20 && (text[sample.color] || 0) < texts * 0.01) {
      const strong = Object.entries(text)
        .filter(([c, n]) => n >= texts * 0.05 && spread(c) < 80 && !c.includes("rgba") && !c.includes("/"))
        .sort((a, b) => contrast(b[0], sample.backgroundColor) - contrast(a[0], sample.backgroundColor))[0];
      if (strong) sample.color = strong[0];
    }
    return sample;
  };
  const aside = "dialog,[role=dialog],[aria-modal=true],[class*=cookie],[id*=cookie],[class*=consent],[id*=consent],[class*=cky-]";
  const action = (selector, props) => {
    // A call to action is often a link styled as a button with no class that
    // says so, as on Vercel and Linear, so filled links shaped like a button
    // count too. Those in the first screen come first. [BD-1753]
    // A wide cap: a hidden mega menu can hold hundreds of links before the hero.
    const all = Array.from(document.querySelectorAll(selector + ",a[href]")).slice(0, 1500).filter((el) => !el.closest(aside));
    const named = (el) => el.tagName !== "A" || !el.matches || el.matches(selector);
    const buttonShaped = (el) => {
      if (named(el)) return true;
      const box = el.getBoundingClientRect();
      return box.height >= 24 && box.height <= 72 && box.width <= 480 && String(el.textContent || "").trim() !== "";
    };
    // The layer that paints a button: the element itself, or a ::before or
    // ::after placed over its whole box, as on Duolingo's green link. [BD-1755]
    const layer = (el) => {
      const own = getComputedStyle(el);
      if (!clear(own.backgroundColor)) return own;
      const box = el.getBoundingClientRect();
      for (const which of ["::before", "::after"]) {
        const ps = getComputedStyle(el, which);
        if (!ps || !ps.content || ps.content === "none" || ps.content === "normal" || clear(ps.backgroundColor)) continue;
        if (ps.position !== "absolute") continue;
        // A layer nobody can see paints nothing. [BD-1755]
        if (ps.display === "none" || ps.visibility === "hidden" || parseFloat(ps.opacity) === 0) continue;
        if (parseFloat(ps.width) >= box.width * 0.8 && parseFloat(ps.height) >= box.height * 0.8) return ps;
      }
      return own;
    };
    const fillOf = (el) => layer(el).backgroundColor;
    const filled = all.filter((el) => seen(el) && buttonShaped(el) && !clear(fillOf(el)));
    const fold = globalThis.innerHeight || 900;
    const first = (el) => el.getBoundingClientRect().top < fold;
    const shown = [...filled.filter(first), ...filled.filter((el) => !first(el))];
    const isPrimaryClass = (t) => t === "primary" || ((t.startsWith("btn") || t.startsWith("button")) && t.endsWith("primary"));
    const primaryClass = shown.find((el) => String(el.className).split(" ").some(isPrimaryClass));
    const colourful = shown.slice(0, 12).reduce((best, el) => (spread(fillOf(el)) > (best ? spread(fillOf(best)) : 39) ? el : best), null);
    // With no colour to go by, the main button is the fill that stands out
    // most from the page: Vercel's black, not its white. [BD-1753]
    const backdrop = ground();
    // A see-through chip would read as its colour at full strength, so only solid fills compete.
    const standout = shown.slice(0, 12).filter((el) => opaque(fillOf(el))).reduce((best, el) => (contrast(fillOf(el), backdrop) > (best ? contrast(fillOf(best), backdrop) : 1) ? el : best), null);
    // The same fill often paints a small header button and the hero's larger
    // one, and the hero's carries the button's real shape. [BD-1753]
    const tallest = (el) =>
      el && shown.slice(0, 12).filter((o) => fillOf(o) === fillOf(el)).reduce((best, o) => (o.getBoundingClientRect().height > best.getBoundingClientRect().height ? o : best), el);
    const fallback = all.find(named) ?? null;
    const chosen = primaryClass ?? tallest(colourful ?? standout) ?? shown[0] ?? fallback;
    const sample = pick(chosen, props);
    if (!sample) return sample;
    // A painting layer carries the fill and the corners; the text colour stays the element's.
    const paint = layer(chosen);
    // A square layer stays square unless the element clips it to its own corners. [BD-1755]
    const overflow = getComputedStyle(chosen).overflow;
    const clips = Boolean(overflow) && overflow !== "visible";
    for (const p of ["backgroundColor", "borderRadius", "cornerShape"]) {
      if (p in sample && paint[p] && !(p === "borderRadius" && clips && parseFloat(paint[p]) === 0)) sample[p] = paint[p];
    }
    return { ...sample, namedPrimary: primaryClass ? "yes" : "" };
  };
  const spacing = () => Object.entries(walk().space).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([length]) => length);
  return {
    body: page(["backgroundColor","color","fontFamily"]),
    heading: pick(document.querySelector("h1,h2"), ["fontFamily"]),
    link: pick(document.querySelector("a[href]"), ["color"]),
    button: action("button,[role=button],.btn,input[type=submit],a[class*=button],a[class*=btn]", ["backgroundColor","color","borderRadius","cornerShape"]),
    input: pick(document.querySelector("input:not([type=hidden]),textarea,select"), ["borderColor","borderRadius"]),
    card: pick(document.querySelector("[class*=card]"), ["backgroundColor","color","borderRadius","boxShadow","cornerShape"]),
    spacing: spacing(),
  };
})())
```
- kind "tokens": a design-tokens JSON export ($value entries, W3C format or the Figma variables API shape with 0..1 rgb floats).

Common vendor names (Shopify's --color-button family) are mapped into empty semantic slots automatically and the mapping is reported in the output.

